using PetShop_App.Dados;
namespace PetShop_App.Telas.Vendas
{

public partial class PaginaEstoque : UserControl
{
    public PaginaEstoque() { InitializeComponent(); if (PetShop_App.Componentes.AmbienteDesign.EstaAtivo(this)) return; Load += async (_, _) => await CarregarAsync(); txtPesquisa.TextChanged += async (_, _) => await CarregarAsync(); btnNovoProduto.Click += async (_, _) => await NovoProdutoAsync(); btnEditarRegistro.Click += async (_, _) => await EditarAsync(); btnExcluirRegistro.Click += async (_, _) => await ExcluirAsync(); }
    private async Task CarregarAsync() { if (PetShop_App.Componentes.AmbienteDesign.EstaAtivo(this)) return; try { var itens = await new RepositorioPetShop().ListarProdutosAsync(txtPesquisa.Text); gradeEstoque.DataSource = itens.Select(x => new { x.Id, x.Codigo, x.Nome, x.Categoria, Preço = x.Preco.ToString("C"), x.Estoque, Mínimo = x.EstoqueMinimo, Situação = x.Estoque <= x.EstoqueMinimo ? "Estoque baixo" : "Normal" }).ToList(); if (gradeEstoque.Columns["Id"] is not null) gradeEstoque.Columns["Id"].Visible = false; lblResumo.Text = $"{itens.Count} produtos · {itens.Count(x => x.Estoque <= x.EstoqueMinimo)} com estoque baixo"; } catch (Exception ex) { MessageBox.Show(ex.Message, "Estoque"); } }
    private async Task NovoProdutoAsync() { using var f = new PetShop_App.Componentes.FormularioCadastro("Cadastrar produto", 620); var codigo = f.Texto("Código/SKU *", "Ex.: RAC-007"); var nome = f.Texto("Nome do produto *"); var categoria = f.Combo("Categoria *"); categoria.Items.AddRange(["Rações", "Petiscos", "Higiene", "Brinquedos", "Acessórios", "Medicamentos", "Outros"]); categoria.SelectedIndex = 0; var preco = f.Numero("Preço de venda (R$) *", 999999, 2); var estoque = f.Numero("Quantidade inicial", 99999); var minimo = f.Numero("Estoque mínimo", 99999); minimo.Value = 5; if (f.ShowDialog(this) != DialogResult.OK) return; if (string.IsNullOrWhiteSpace(codigo.Text) || string.IsNullOrWhiteSpace(nome.Text) || preco.Value <= 0) { MessageBox.Show("Informe código, nome e preço do produto.", "Campos obrigatórios"); return; } try { await new RepositorioPetShop().SalvarProdutoAsync(new PetShop_App.Modelos.Produto { Codigo = codigo.Text.Trim().ToUpperInvariant(), Nome = nome.Text.Trim(), Categoria = categoria.Text, Preco = preco.Value, Estoque = (int)estoque.Value, EstoqueMinimo = (int)minimo.Value }); txtPesquisa.Clear(); await CarregarAsync(); MessageBox.Show("Produto cadastrado com sucesso!", "Estoque"); } catch (MySqlConnector.MySqlException ex) when (ex.Number == 1062) { MessageBox.Show("Já existe um produto com esse código.", "Código duplicado"); } }
    private async Task EditarAsync() { if (gradeEstoque.CurrentRow?.Cells["Id"].Value is not int id) return; var p = (await new RepositorioPetShop().ListarProdutosAsync()).First(x => x.Id == id); using var f = new PetShop_App.Componentes.FormularioCadastro("Editar produto", 620); var nome = f.Texto("Nome *"); nome.Text = p.Nome; var codigo = f.Texto("Código *"); codigo.Text = p.Codigo; var categoria = f.Texto("Categoria"); categoria.Text = p.Categoria; var preco = f.Numero("Preço", 999999, 2); preco.Value = p.Preco; var estoque = f.Numero("Estoque", 99999); estoque.Value = p.Estoque; var minimo = f.Numero("Estoque mínimo", 99999); minimo.Value = p.EstoqueMinimo; if (f.ShowDialog(this) != DialogResult.OK) return; p.Nome = nome.Text; p.Codigo = codigo.Text; p.Categoria = categoria.Text; p.Preco = preco.Value; p.Estoque = (int)estoque.Value; p.EstoqueMinimo = (int)minimo.Value; await new RepositorioPetShop().AtualizarProdutoAsync(p); await CarregarAsync(); }
    private async Task ExcluirAsync() { if (gradeEstoque.CurrentRow?.Cells["Id"].Value is not int id || !PetShop_App.Componentes.BotoesCrud.Confirmar("o produto selecionado")) return; try { await new RepositorioPetShop().ExcluirProdutoAsync(id); await CarregarAsync(); } catch (MySqlConnector.MySqlException) { MessageBox.Show("Este produto possui vendas vinculadas e não pode ser removido."); } }
}

}
